declare const PRODUCT_SEARCH_QUERY = "\n  query productSearch(\n    $phrase: String!\n    $pageSize: Int\n    $currentPage: Int = 1\n    $filter: [SearchClauseInput!]\n    $sort: [ProductSearchSortInput!]\n    $context: QueryContextInput\n  ) {\n    attributeMetadata {\n      sortable {\n        label\n        attribute\n        numeric\n      }\n      filterableInSearch {\n        label\n        attribute\n        numeric\n      }\n    }\n\n    productSearch(\n      phrase: $phrase\n      page_size: $pageSize\n      current_page: $currentPage\n      filter: $filter\n      sort: $sort\n      context: $context\n    ) {\n      total_count\n      items {\n        ...ProductView\n      }\n      facets {\n        ...Facet\n      }\n      page_info {\n        current_page\n        page_size\n        total_pages\n      }\n    }\n  }\n  \n  fragment ProductView on ProductSearchItem {\n    productView {\n      __typename\n      sku\n      name\n      inStock\n      url\n      urlKey\n      attributes(roles: []) {\n        name\n        label\n        value\n        roles\n      }\n      images {\n        label\n        url\n        roles\n      }\n      ... on ComplexProductView {\n        priceRange {\n          maximum {\n            final {\n              amount {\n                value\n                currency\n              }\n            }\n            regular {\n              amount {\n                value\n                currency\n              }\n            }\n          }\n          minimum {\n            final {\n              amount {\n                value\n                currency\n              }\n            }\n            regular {\n              amount {\n                value\n                currency\n              }\n            }\n          }\n        }\n        options {\n          id\n          title\n          values {\n            title\n            ... on ProductViewOptionValueSwatch {\n              id\n              inStock\n              type\n              value\n            }\n          }\n        }\n      }\n      ... on SimpleProductView {\n        price {\n          final {\n            amount {\n              value\n              currency\n            }\n          }\n          regular {\n            amount {\n              value\n              currency\n            }\n          }\n        }\n      }\n    }\n    highlights {\n      attribute\n      value\n      matched_words\n    }\n  }\n\n  \n  fragment Facet on Aggregation {\n    title\n    attribute\n    buckets {\n      title\n      __typename\n      ... on CategoryView {\n        name\n        count\n        path\n      }\n      ... on ScalarBucket {\n        count\n      }\n      ... on RangeBucket {\n        from\n        to\n        count\n      }\n      ... on StatsBucket {\n        min\n        max\n      }\n    }\n  }\n\n";
export { PRODUCT_SEARCH_QUERY };
